using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "The science of numbers, quantity, and space." },
        new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = 4, Name = "English", Code = "ENG", Description = "Literature, writing, and language studies." },
        new() { Id = 5, Name = "Biology", Code = "BIO", Description = "Study of living organisms and their interactions." },
    ];

    private readonly List<Course> _courses =
    [
        new()
        {
            Id = 1, Title = "Introduction to Programming", Code = "CS 101",
            Description = "A foundational course covering programming concepts using Python. Topics include variables, control flow, functions, data structures, and basic object-oriented programming.",
            Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Alice Chen",
            InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses and has published research on CS pedagogy.",
            DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true
        },
        new()
        {
            Id = 2, Title = "Data Structures and Algorithms", Code = "CS 201",
            Description = "Study of fundamental data structures (lists, trees, graphs, hash tables) and algorithm design techniques including sorting, searching, and dynamic programming.",
            Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. Brian Lee",
            InstructorBio = "Dr. Lee specializes in algorithm optimization and competitive programming. He has coached multiple ICPC teams.",
            DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true
        },
        new()
        {
            Id = 3, Title = "Operating Systems", Code = "CS 350",
            Description = "Covers process management, memory management, file systems, and concurrency. Includes hands-on labs with a teaching OS kernel.",
            Credits = 4, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Carol Martinez",
            InstructorBio = "Dr. Martinez worked at a major OS vendor for a decade before joining academia. Her research focuses on distributed systems.",
            DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false
        },
        new()
        {
            Id = 4, Title = "Calculus I", Code = "MATH 151",
            Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics.",
            Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. David Park",
            InstructorBio = "Dr. Park is an award-winning educator with a focus on making calculus accessible through visual and applied methods.",
            DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true
        },
        new()
        {
            Id = 5, Title = "Linear Algebra", Code = "MATH 220",
            Description = "Vectors, matrices, linear transformations, eigenvalues, and applications to data science and engineering.",
            Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Emily Zhao",
            InstructorBio = "Dr. Zhao researches applications of linear algebra in machine learning and has authored a popular open textbook.",
            DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false
        },
        new()
        {
            Id = 6, Title = "Classical Mechanics", Code = "PHYS 201",
            Description = "Newtonian mechanics, conservation laws, oscillations, and an introduction to Lagrangian mechanics.",
            Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Frank Novak",
            InstructorBio = "Dr. Novak is a theoretical physicist whose teaching emphasizes intuition and problem-solving skills.",
            DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false
        },
        new()
