@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Enrollment Request - University Course Catalog</PageTitle>

<h1>Submit Enrollment Request</h1>
<p>Complete the form below to request enrollment in a course.</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Enrollment Request Submitted</h4>
        <p>Thank you, <strong>@_model.StudentName</strong>. Your request to enroll in
            <strong>@(_selectedCourseName)</strong> has been received.</p>
        <a href="/courses" class="btn btn-primary">Browse More Courses</a>
    </div>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="enrollment" class="mt-3" style="max-width: 600px;">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="studentName" class="form-label">Full Name</label>
            <InputText id="studentName" class="form-control" @bind-Value="_model.StudentName" />
            <ValidationMessage For="() => _model.StudentName" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <InputText id="studentId" class="form-control" @bind-Value="_model.StudentId" />
            <ValidationMessage For="() => _model.StudentId" class="text-danger" />
            <div class="form-text">6–12 alphanumeric characters (e.g., STU12345)</div>
        </div>

        <div class="mb-3">
            <label for="courseSelect" class="form-label">Course</label>
            <InputSelect id="courseSelect" class="form-select" @bind-Value="_model.CourseId">
                <option value="0">-- Select a course --</option>
                @foreach (var course in _courses)
                {
                    <option value="@course.Id">@course.Code - @course.Title</option>
                }
            </InputSelect>
            <ValidationMessage For="() => _model.CourseId" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
        <a href="/courses" class="btn btn-secondary ms-2">Cancel</a>
    </EditForm>
}

@code {
    [SupplyParameterFromQuery] public int? CourseId { get; set; }
    [SupplyParameterFromForm] private EnrollmentRequest _model { get; set; } = new();

    private List<Course> _courses = [];
    private bool _submitted;
    private string _selectedCourseName = string.Empty;

    protected override void OnInitialized()
    {
        _courses = CatalogService.GetCourses();
        if (CourseId.HasValue && _model.CourseId == 0)
            _model.CourseId = CourseId.Value;
    }

    private void HandleSubmit()
    {
        var course = CatalogService.GetCourse(_model.CourseId);
        _selectedCourseName = course is not null ? $"{course.Code} - {course.Title}" : "Unknown";
        _submitted = CatalogService.SubmitEnrollmentRequest(_model);
    }
}

